export default function ({ values, previous }) {
  const rows = values ?? [];
  if (!rows.length) throw Error("Missing sheet headers");
  const h = rows[0],
    required = [
      "input",
      "enrichment_status",
      "domain",
      "linkedinUrl",
      "market",
      "cheapest_plan",
      "has_entreprise_plan",
      "has_API",
      "has_free_trial",
      "integrations",
      "last_case_study_link",
    ];
  for (const k of required)
    if (h.filter((x) => x === k).length !== 1) throw Error("Missing or duplicate header: " + k);
  let i = previous?.index ?? 1;
  while (
    i < rows.length &&
    (!rows[i][h.indexOf("input")] || rows[i][h.indexOf("enrichment_status")])
  )
    i++;
  const more = i < rows.length;
  return {
    state: { index: i + 1 },
    more,
    row: i + 1,
    company: more ? String(rows[i][h.indexOf("input")]) : "",
    headers: h,
  };
}

