export default async function ({ row, company, headers, analysis }, ctx) {
  const key = "sales-research:" + JSON.stringify([row, company]),
    s = await ctx.state.get(key);
  if (s?.status === "pending") throw Error("Inspect sheet before retrying uncertain update");
  if (s?.status === "done")
    return { skip: true, key, data: [{ range: "'Sheet1'!A1", values: [[""]] }] };
  const a = typeof analysis === "string" ? JSON.parse(analysis) : analysis;
  if (!a || typeof a !== "object") throw Error("Invalid research result");
  const map = {
    domain: a.domain,
    linkedinUrl: a.linkedinUrl,
    market: a.market,
    cheapest_plan: a.cheapest_plan,
    has_entreprise_plan: a.has_enterprise_plan,
    has_API: a.has_API,
    has_free_trial: a.has_free_trial,
    integrations: Array.isArray(a.integrations) ? a.integrations.join(", ") : "",
    last_case_study_link: a.case_study_link,
    enrichment_status: "done",
  };
  const col = (i) => {
    let s = "";
    for (i++; i; i = Math.floor((i - 1) / 26)) s = String.fromCharCode(65 + ((i - 1) % 26)) + s;
    return s;
  };
  const data = Object.entries(map).map(([k, v]) => ({
    range: "'Sheet1'!" + col(headers.indexOf(k)) + row,
    values: [[v ?? ""]],
  }));
  await ctx.state.set(key, { status: "pending" });
  return { skip: false, key, data };
}

