export default function ({ body }) {
  if (body?.error) throw Error("Reverse search failed");
  return {
    result: JSON.stringify(
      (body?.organic_results ?? []).map((x) => ({
        title: x.title,
        link: x.link,
        description: x.snippet,
      })),
    ),
  };
}

